# ============================================================

APP_NAME = "DT1Masker"

APP_VERSION = "1.0"
APP_FILE_VERSION = "1.0.0.0"

APP_COMPANY = "GimliHC"

APP_DESCRIPTION = (
    "DT1Mask Creator / Decoder for Diablo 2 Modding"
)

