APP_INTERNAL_NAME = "DT1Masker"
APP_ORIGINAL_FILENAME = "DT1Masker.exe"


# ============================================================
# SVG Icon
# ============================================================

def create_application_icon():
    """
    Create a QIcon directly from the embedded SVG.

    No external SVG or ICO file is required.

    Multiple resolutions are rendered into the QIcon so that
    Windows / Qt can select an appropriate size for the
    title bar, taskbar, dialogs, etc.
    """

    if isinstance(SVG_ICON, str):
        svg_data = SVG_ICON.encode("utf-8")
    else:
        svg_data = SVG_ICON

    renderer = QSvgRenderer(
        QByteArray(svg_data)
    )

    icon = QIcon()

    # Render several sizes from the same master SVG.
    #
    # This gives Qt suitable versions for different UI
    # situations while keeping SVG_ICON as the master source.
    for size in (16, 20, 24, 32, 48, 64, 96, 128, 256):

        pixmap = QPixmap(size, size)

        pixmap.fill(Qt.GlobalColor.transparent)

        painter = QPainter(pixmap)

        renderer.render(
            painter,
            pixmap.rect()
        )

        painter.end()

        icon.addPixmap(pixmap)

    return icon


# ============================================================
# Configuration
# ============================================================

MAX_FILES = 32
MAX_MASK = 0xFFFFFFFF


# ============================================================
# Dt1Mask logic
# ============================================================

def files_to_mask(files):
    """
    Convert a list of file numbers to a Dt1Mask.

    File 1  = 1
    File 2  = 2
    File 3  = 4
    ...
    File 32 = 2147483648
    """

    mask = 0

    for file_number in files:

        if not 1 <= file_number <= MAX_FILES:
            raise ValueError(
                f"File {file_number} is invalid.\n\n"
                f"Valid files are File 1 through File {MAX_FILES}."
            )

        mask |= 1 << (file_number - 1)

    return mask


def mask_to_files(mask):
    """
    Convert a Dt1Mask to a list of active files.
    """

    if not 0 <= mask <= MAX_MASK:
        raise ValueError(
            "Dt1Mask must be between "
            "0 and 4,294,967,295."
        )

    files = []

    for file_number in range(1, MAX_FILES + 1):

        bit = 1 << (file_number - 1)

        if mask & bit:
            files.append(file_number)

    return files


def parse_files(text):
    """
    Parse user input such as:

        1,5,6,12

    or:

        File 1, File 5, File 6, File 12

    or:

        1 5 6 12
    """

    numbers = re.findall(r"\d+", text)

    if not numbers:
        return []

    files = sorted(
        set(int(number) for number in numbers)
    )

    for file_number in files:

        if not 1 <= file_number <= MAX_FILES:
            raise ValueError(
                f"File {file_number} is invalid.\n\n"
                f"Valid files are File 1 through File {MAX_FILES}."
            )

    return files


# ============================================================
# Main Window
# ============================================================

class Dt1MaskerWindow(QMainWindow):

    def __init__(self):
        super().__init__()

        self.updating = False

        self.setWindowTitle(APP_NAME)

        self.setMinimumSize(960, 780)

        # Create the icon directly from the embedded SVG.
        self.application_icon = create_application_icon()

        self.setup_icon()
        self.setup_ui()

    # ========================================================
    # Window icon
    # ========================================================

    def setup_icon(self):

        self.setWindowIcon(
            self.application_icon
        )

    # ========================================================
    # UI
    # ========================================================

    def setup_ui(self):

        central = QWidget()
        self.setCentralWidget(central)

        main_layout = QVBoxLayout(central)

        main_layout.setContentsMargins(
            32, 28, 32, 28
        )

        main_layout.setSpacing(20)

        # ----------------------------------------------------
        # Header
        # ----------------------------------------------------

        header = QVBoxLayout()
        header.setSpacing(4)

        title = QLabel(
            APP_DESCRIPTION
        )

        title.setObjectName("title")

        subtitle = QLabel(
            "Select DT1 files or enter a Dt1Mask value. "
            "Everything updates automatically."
        )

        subtitle.setObjectName("subtitle")

        header.addWidget(title)
        header.addWidget(subtitle)

        main_layout.addLayout(header)

        # ----------------------------------------------------
        # Conversion cards
        # ----------------------------------------------------

        cards_layout = QHBoxLayout()
        cards_layout.setSpacing(18)

        cards_layout.addWidget(
            self.create_files_card()
        )

        cards_layout.addWidget(
            self.create_mask_card()
        )

        main_layout.addLayout(cards_layout)

        # ----------------------------------------------------
        # File selector
        # ----------------------------------------------------

        main_layout.addWidget(
            self.create_file_selector_card()
        )

        # ----------------------------------------------------
        # Footer
        # ----------------------------------------------------

        footer_text = (
            f"{APP_NAME} "
            f"v{APP_VERSION}"
        )

        if APP_COPYRIGHT:
            footer_text += (
                f"  •  {APP_COPYRIGHT}"
            )

        footer = QLabel(footer_text)

        footer.setObjectName("footer")

        footer.setAlignment(
            Qt.AlignmentFlag.AlignCenter
        )

        main_layout.addWidget(footer)

    # ========================================================
    # Files card
    # ========================================================

    def create_files_card(self):

        card = QFrame()
        card.setObjectName("card")

        layout = QVBoxLayout(card)

        layout.setContentsMargins(
            24, 22, 24, 22
        )

        layout.setSpacing(14)

        title = QLabel("Files → Dt1Mask")
        title.setObjectName("cardTitle")

        description = QLabel(
            "Enter files manually or select them "
            "using the buttons below."
        )

        description.setObjectName("description")

        self.files_input = QLineEdit()

        self.files_input.setPlaceholderText(
            "Example: File 1, File 5, File 6, File 12"
        )

        self.files_input.setObjectName(
            "input"
        )

        self.files_input.editingFinished.connect(
            self.files_text_changed
        )

        layout.addWidget(title)
        layout.addWidget(description)
        layout.addWidget(self.files_input)

        mask_label = QLabel("Dt1Mask")
        mask_label.setObjectName("fieldLabel")

        self.mask_result = QLineEdit()

        self.mask_result.setReadOnly(True)
        self.mask_result.setObjectName("result")

        copy_button = QPushButton("Copy")

        copy_button.setObjectName(
            "secondaryButton"
        )

        copy_button.clicked.connect(
            lambda: self.copy_text(
                self.mask_result.text()
            )
        )

        result_row = QHBoxLayout()

        result_row.setSpacing(8)

        result_row.addWidget(
            self.mask_result
        )

        result_row.addWidget(
            copy_button
        )

        layout.addWidget(mask_label)
        layout.addLayout(result_row)

        return card

    # ========================================================
    # Mask card
    # ========================================================

    def create_mask_card(self):

        card = QFrame()
        card.setObjectName("card")

        layout = QVBoxLayout(card)

        layout.setContentsMargins(
            24, 22, 24, 22
        )

        layout.setSpacing(14)

        title = QLabel("Dt1Mask → Files")
        title.setObjectName("cardTitle")

        description = QLabel(
            "Enter a Dt1Mask to highlight the "
            "corresponding DT1 files."
        )

        description.setObjectName(
            "description"
        )

        self.mask_input = QLineEdit()

        self.mask_input.setPlaceholderText(
            "Enter a Dt1Mask value..."
        )

        self.mask_input.setObjectName(
            "input"
        )

        self.mask_input.textChanged.connect(
            self.mask_text_changed
        )

        layout.addWidget(title)
        layout.addWidget(description)
        layout.addWidget(self.mask_input)

        files_label = QLabel("Files")
        files_label.setObjectName("fieldLabel")

        self.files_result = QLineEdit()

        self.files_result.setReadOnly(True)
        self.files_result.setObjectName("result")

        copy_button = QPushButton("Copy")

        copy_button.setObjectName(
            "secondaryButton"
        )

        copy_button.clicked.connect(
            lambda: self.copy_text(
                self.files_result.text()
            )
        )

        result_row = QHBoxLayout()

        result_row.setSpacing(8)

        result_row.addWidget(
            self.files_result
        )

        result_row.addWidget(
            copy_button
        )

        layout.addWidget(files_label)
        layout.addLayout(result_row)

        return card

    # ========================================================
    # File selector
    # ========================================================

    def create_file_selector_card(self):

        card = QFrame()
        card.setObjectName("card")

        layout = QVBoxLayout(card)

        layout.setContentsMargins(
            24, 22, 24, 22
        )

        layout.setSpacing(14)

        # ----------------------------------------------------
        # Header
        # ----------------------------------------------------

        header = QHBoxLayout()

        title = QLabel("DT1 File Selector")
        title.setObjectName("cardTitle")

        self.selected_label = QLabel(
            "0 / 32 selected"
        )

        self.selected_label.setObjectName(
            "selectedLabel"
        )

        header.addWidget(title)
        header.addStretch()
        header.addWidget(
            self.selected_label
        )

        layout.addLayout(header)

        description = QLabel(
            "Click a file to activate or deactivate it. "
            "Active files are highlighted in green."
        )

        description.setObjectName(
            "description"
        )

        layout.addWidget(description)

        # ----------------------------------------------------
        # Controls
        # ----------------------------------------------------

        controls = QHBoxLayout()
        controls.setSpacing(8)

        select_all = QPushButton(
            "Select All"
        )

        select_all.setObjectName(
            "secondaryButton"
        )

        select_all.clicked.connect(
            self.select_all_files
        )

        clear_all = QPushButton(
            "Clear All"
        )

        clear_all.setObjectName(
            "secondaryButton"
        )

        clear_all.clicked.connect(
            self.clear_all_files
        )

        invert = QPushButton(
            "Invert Selection"
        )

        invert.setObjectName(
            "secondaryButton"
        )

        invert.clicked.connect(
            self.invert_selection
        )

        controls.addWidget(select_all)
        controls.addWidget(clear_all)
        controls.addWidget(invert)
        controls.addStretch()

        layout.addLayout(controls)

        # ----------------------------------------------------
        # File buttons
        # ----------------------------------------------------

        self.file_grid = QGridLayout()
        self.file_grid.setSpacing(8)

        self.file_buttons = []

        for i in range(MAX_FILES):

            file_number = i + 1

            button = QPushButton(
                f"File {file_number}"
            )

            button.setCheckable(True)
            button.setMinimumHeight(46)

            button.setProperty(
                "file_number",
                file_number
            )

            button.clicked.connect(
                self.file_button_clicked
            )

            self.file_buttons.append(
                button
            )

            row = i // 8
            column = i % 8

            self.file_grid.addWidget(
                button,
                row,
                column
            )

            self.update_button_style(
                button,
                False
            )

        layout.addLayout(
            self.file_grid
        )

        return card

    # ========================================================
    # File button clicked
    # ========================================================

    def file_button_clicked(self):

        if self.updating:
            return

        sender = self.sender()

        if sender is None:
            return

        selected = sender.isChecked()

        self.update_button_style(
            sender,
            selected
        )

        self.sync_from_buttons()

    # ========================================================
    # Synchronize everything from file buttons
    # ========================================================

    def sync_from_buttons(self):

        files = []

        for i, button in enumerate(
            self.file_buttons
        ):

            if button.isChecked():
                files.append(i + 1)

        self.updating = True

        try:

            if not files:

                self.files_input.clear()
                self.mask_result.clear()
                self.mask_input.clear()
                self.files_result.clear()

                self.update_selection_counter()

                return

            file_text = ", ".join(
                f"File {number}"
                for number in files
            )

            self.files_input.setText(
                file_text
            )

            mask = files_to_mask(files)

            mask_text = str(mask)

            self.mask_result.setText(
                mask_text
            )

            self.mask_input.setText(
                mask_text
            )

            self.files_result.setText(
                file_text
            )

            self.update_selection_counter()

        finally:
            self.updating = False

    # ========================================================
    # Files textbox changed
    # ========================================================

    def files_text_changed(self):

        if self.updating:
            return

        text = self.files_input.text().strip()

        if not text:

            self.clear_all_files()
            return

        try:

            files = parse_files(text)

            self.updating = True

            try:

                self.set_selected_files(
                    files
                )

                mask = files_to_mask(files)

                self.mask_result.setText(
                    str(mask)
                )

                self.mask_input.setText(
                    str(mask)
                )

                self.files_result.setText(
                    ", ".join(
                        f"File {number}"
                        for number in files
                    )
                )

            finally:
                self.updating = False

        except ValueError as error:

            self.show_error(
                str(error)
            )

    # ========================================================
    # Dt1Mask textbox changed
    # ========================================================

    def mask_text_changed(self, text):

        if self.updating:
            return

        text = text.strip()

        if not text:

            self.updating = True

            try:

                self.set_selected_files([])

                self.files_input.clear()
                self.mask_result.clear()
                self.files_result.clear()

            finally:
                self.updating = False

            return

        try:

            mask = int(text)

            if not 0 <= mask <= MAX_MASK:
                raise ValueError(
                    "Dt1Mask must be between "
                    "0 and 4,294,967,295."
                )

            files = mask_to_files(mask)

            self.updating = True

            try:

                self.set_selected_files(
                    files
                )

                if files:

                    file_text = ", ".join(
                        f"File {number}"
                        for number in files
                    )

                    self.files_input.setText(
                        file_text
                    )

                    self.files_result.setText(
                        file_text
                    )

                    self.mask_result.setText(
                        str(mask)
                    )

                else:

                    self.files_input.clear()
                    self.files_result.clear()
                    self.mask_result.setText(
                        "0"
                    )

            finally:
                self.updating = False

        except ValueError:
            return

    # ========================================================
    # Set selected files
    # ========================================================

    def set_selected_files(self, files):

        selected = set(files)

        for i, button in enumerate(
            self.file_buttons
        ):

            file_number = i + 1

            is_selected = (
                file_number in selected
            )

            button.setChecked(
                is_selected
            )

            self.update_button_style(
                button,
                is_selected
            )

        self.update_selection_counter()

    # ========================================================
    # Select all
    # ========================================================

    def select_all_files(self):

        files = list(
            range(1, MAX_FILES + 1)
        )

        self.set_selected_files(
            files
        )

        self.sync_from_buttons()

    # ========================================================
    # Clear all
    # ========================================================

    def clear_all_files(self):

        self.updating = True

        try:

            self.set_selected_files([])

            self.files_input.clear()
            self.mask_result.clear()
            self.mask_input.clear()
            self.files_result.clear()

        finally:
            self.updating = False

    # ========================================================
    # Invert selection
    # ========================================================

    def invert_selection(self):

        self.updating = True

        try:

            for button in self.file_buttons:

                new_state = (
                    not button.isChecked()
                )

                button.setChecked(
                    new_state
                )

                self.update_button_style(
                    button,
                    new_state
                )

        finally:
            self.updating = False

        self.sync_from_buttons()

    # ========================================================
    # File button styling
    # ========================================================

    def update_button_style(
        self,
        button,
        selected
    ):

        if selected:

            button.setStyleSheet("""
                QPushButton {
                    background-color: #20c997;
                    color: #061a13;
                    border: 1px solid #38d9a9;
                    border-radius: 9px;
                    font-weight: 700;
                }

                QPushButton:hover {
                    background-color: #38d9a9;
                    border: 1px solid #63e6be;
                }

                QPushButton:pressed {
                    background-color: #12b886;
                }
            """)

        else:

            button.setStyleSheet("""
                QPushButton {
                    background-color: #1b2330;
                    color: #8b949e;
                    border: 1px solid #303b4d;
                    border-radius: 9px;
                    font-weight: 500;
                }

                QPushButton:hover {
                    background-color: #252e3d;
                    color: #f0f6fc;
                    border: 1px solid #4b5563;
                }

                QPushButton:pressed {
                    background-color: #303b4d;
                    color: #ffffff;
                }
            """)

    # ========================================================
    # Selection counter
    # ========================================================

    def update_selection_counter(self):

        count = sum(
            button.isChecked()
            for button in self.file_buttons
        )

        self.selected_label.setText(
            f"{count} / {MAX_FILES} selected"
        )

    # ========================================================
    # Copy
    # ========================================================

    def copy_text(self, text):

        if text:
            QApplication.clipboard().setText(
                text
            )

    # ========================================================
    # Error dialog
    # ========================================================

    def show_error(self, message):

        QMessageBox.warning(
            self,
            APP_NAME,
            message
        )


