# ============================================================
# Main
# ============================================================

def main():

    app = QApplication(sys.argv)

    # --------------------------------------------------------
    # Application metadata
    # --------------------------------------------------------

    app.setApplicationName(
        APP_NAME
    )

    app.setApplicationVersion(
        APP_VERSION
    )

    app.setOrganizationName(
        APP_COMPANY
    )

    app.setStyle("Fusion")
    app.setStyleSheet(STYLE)

    # --------------------------------------------------------
    # Application icon
    # --------------------------------------------------------
    #
    # The icon is generated directly from SVG_ICON.
    #
    # No icon.ico is required here.

    application_icon = create_application_icon()

    app.setWindowIcon(
        application_icon
    )

    # --------------------------------------------------------
    # Main window
    # --------------------------------------------------------

    window = Dt1MaskerWindow()

    # Explicitly set the same icon on the window.
    #
    # This ensures the title-bar/window icon uses the
    # embedded SVG-derived icon as well.

    window.setWindowIcon(
        application_icon
    )

    window.show()

    sys.exit(
        app.exec()
    )


if __name__ == "__main__":
    main()
